const results = await Promise.allSettled([
  tools.exec_command({cmd:"pwd && git status --short && git branch --show-current && git remote -v && cat docs/prds/codex-packaged-workflow/codex-packaged-workflow-prd.md",max_output_tokens:6500}),
  tools.exec_command({cmd:"cat /HOME/.agents/skills/dwk-message-writing-standards/SKILL.md",max_output_tokens:6000})
]); for(let i=0;i<results.length;i++) text({i,...results[i]});
text(ALL_TOOLS.filter(x=>/github|pull request/.test(x.name+" "+x.description)).map(x=>({name:x.name,description:x.description.slice(0,180)})).slice(0,60));
